from datetime import date

class Loyalty:
    def __init__(self) -> None:
        self.customers = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        points_earned = int(amount // 10)
        if customer not in self.customers:
            self.customers[customer] = {"purchases": [], "redemptions": []}

        self.customers[customer]["purchases"].append((amount, day))
        return points_earned

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        if customer not in self.customers:
            return 0

        points_earned = sum(int(amount // 10) for amount, purchase_day in self.customers[customer]["purchases"] if purchase_day <= day)
        points_redeemed = sum(points for points, redemption_day in self.customers[customer]["redemptions"] if redemption_day <= day)

        return points_earned - points_redeemed

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points."""
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")

        if points > self.balance(customer, day):
            raise ValueError("Insufficient points to redeem")

        if customer not in self.customers:
            self.customers[customer] = {"purchases": [], "redemptions": []}

        self.customers[customer]["redemptions"].append((points, day))
